'use strict';
// 每个角色的数据：曲名、主题色、表情、原创测试旋律。
const tracks=[
 {title:'Ditto',color:'#91c9ff',tag:'BLUE',face:'(｡•ᴗ-)✧',notes:[60,64,67,71,67,64,62,67]},
 {title:'OMG',color:'#ff9dd1',tag:'PINK',face:'(★o★)',notes:[65,69,72,77,72,69,67,72]},
 {title:'Hype Boy',color:'#b6ee85',tag:'GREEN',face:'(¬‿¬)✦',notes:[57,60,64,67,69,67,64,60]},
 {title:'Attention',color:'#ffe998',tag:'YELLOW',face:'(⁄ ⁄•⁄ω⁄•⁄ ⁄)',notes:[62,65,69,74,69,65,64,69]},
 {title:'Cookie',color:'#cfb0ff',tag:'PURPLE',face:'(>ᴗ<)♡',notes:[64,67,71,76,74,71,67,64]}
];
const $=id=>document.getElementById(id),audio=$('audio');let current=0,request=0;const urls=new Map(),custom=new Map(),demo=new Set();
// 完全本地生成 30 秒 WAV：测试音色不包含 NewJeans 的旋律或录音。
function makeDemo(index){if(urls.has(index))return urls.get(index);const rate=16000,length=rate*30,buffer=new ArrayBuffer(44+length*2),v=new DataView(buffer);const word=(at,s)=>[...s].forEach((c,i)=>v.setUint8(at+i,c.charCodeAt(0)));word(0,'RIFF');v.setUint32(4,36+length*2,true);word(8,'WAVE');word(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);word(36,'data');v.setUint32(40,length*2,true);const beat=.29+index*.035;for(let n=0;n<length;n++){const t=n/rate,pos=t%beat,note=tracks[index].notes[Math.floor(t/beat)%8],freq=440*2**((note-69)/12),env=Math.min(1,pos/.012)*Math.exp(-pos*9),fade=Math.min(1,t/.05,(30-t)/.3);const value=(Math.sin(2*Math.PI*freq*t)*.18+Math.sin(4*Math.PI*freq*t)*.035)*env*fade;v.setInt16(44+n*2,value*32767,true)}const url=URL.createObjectURL(new Blob([buffer],{type:'audio/wav'}));urls.set(index,url);return url}
tracks.forEach((t,i)=>{const b=document.createElement('button');b.className='character';b.style.left=([11,31,50,69,87][i]-8)+'%';b.style.setProperty('--char-color',t.color);b.setAttribute('aria-label',`Play ${t.title}，${t.tag}`);b.innerHTML=`<span class="expression" aria-hidden="true">${t.face}</span>`;b.addEventListener('click',()=>select(i,true));$('characters').append(b)});
function update(){const t=tracks[current];document.documentElement.style.setProperty('--accent',t.color);document.querySelector('.player').style.setProperty('--accent',t.color);$('track-title').textContent=t.title;$('track-kicker').textContent=`0${current+1} / ${t.tag}`;$('audio-kind').textContent=custom.has(current)?`Local audio · ${custom.get(current).name}`:(demo.has(current)?'Original demo audio · Not the original song':'User-provided audio · '+t.title+'.mp4');document.querySelectorAll('.character').forEach((b,i)=>{b.classList.toggle('selected',i===current);b.setAttribute('aria-pressed',String(i===current))});}
async function start(){const id=++request;try{await audio.play();if(id===request)$('status').textContent=`Now playing ${tracks[current].title} · ${custom.has(current)?'Your local audio':demo.has(current)?'Original demo':'User-provided audio'}`;}catch(e){if(id===request&&e.name!=='AbortError')$('status').textContent='Unable to play. Try again or choose a supported audio file.';}}
function select(i,play=false){if(i!==current||!audio.getAttribute('src')){request++;audio.pause();current=i;audio.src=custom.get(i)?.url||(demo.has(i)?makeDemo(i):'audio/'+encodeURIComponent(tracks[i].title)+'.mp4');audio.load();$('seek').value=0;$('elapsed').textContent='0:00';$('duration').textContent='…';$('status').textContent='Selected: '+tracks[i].title}update();if(play){start();document.dispatchEvent(new CustomEvent('room-track-selected',{detail:{index:i}}))}}
function playback(){document.body.classList.toggle('playing',!audio.paused);$('play').textContent=audio.paused?'▶':'Ⅱ';$('play').setAttribute('aria-label',audio.paused?'Play':'Pause')}
$('play').onclick=()=>{if(audio.paused)start();else{request++;audio.pause();$('status').textContent='Paused · Press play to continue.'}};$('prev').onclick=()=>select((current+4)%5,true);$('next').onclick=()=>select((current+1)%5,true);
const time=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
audio.addEventListener('play',playback);audio.addEventListener('pause',playback);audio.addEventListener('ended',()=>select((current+1)%5,true));audio.addEventListener('loadedmetadata',()=>{if(Number.isFinite(audio.duration)){$('seek').max=audio.duration;$('duration').textContent=time(audio.duration)}});audio.addEventListener('timeupdate',()=>{$('seek').value=audio.currentTime;$('elapsed').textContent=time(audio.currentTime)});audio.addEventListener('error',()=>{$('status').textContent='Unable to read this audio. Choose a supported MP3, WAV, M4A or MP4 file.';playback()});$('seek').oninput=e=>{if(Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)};
$('audio-file').onchange=e=>{const file=e.target.files[0];if(!file)return;const old=custom.get(current);if(old)URL.revokeObjectURL(old.url);custom.set(current,{url:URL.createObjectURL(file),name:file.name});request++;audio.pause();audio.removeAttribute('src');select(current,true);e.target.value='';};
$('reset-audio').onclick=()=>{const old=custom.get(current);if(old){URL.revokeObjectURL(old.url);custom.delete(current)}demo.add(current);request++;audio.pause();audio.removeAttribute('src');select(current,false);$('status').textContent='Original demo audio restored.'};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else $('status').textContent='Fullscreen is unavailable. Rotate your device for landscape mode.'}catch{$('status').textContent='Unable to enter fullscreen. Try rotating your device.'}};
select(0);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_music_card',description:'Select a song card without starting playback.',inputSchema:{type:'object',properties:{index:{type:'integer',minimum:0,maximum:4}},required:['index'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!Number.isInteger(input.index)||input.index<0||input.index>4)throw new Error('index must be between 0 and 4');select(input.index,false);return {title:tracks[current].title,playing:!audio.paused}}})).catch(()=>{});}catch{}}

